arguments.prompt:
You are working in /tmp/sv-8c8f5fe33ae24750bc84a56bf4b15fd3/ShipmentTracker. This is a Blazor Web App with Interactive Auto Global mode and Individual authentication already scaffolded.

Project structure:
- `ShipmentTracker/` - server project
- `ShipmentTracker.Client/` - client project (interactive components go here)

The app is for a logistics company that tracks shipments. Requirements:
- Dispatchers view a list of shipments with status and destination
- Customers check their shipment status and estimated delivery
- Authentication with individual accounts (already scaffolded)

## Tasks

### 1. Remove template pages
Delete these files from `ShipmentTracker.Client/Pages/`:
- Counter.razor
- Weather.razor

### 2. Create shared models in the Client project

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

### 3. Create service interface in Client project

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 4. Create Client-side HTTP implementation

Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentHttpService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentHttpService(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await _http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        await _http.PutAsJsonAsync($"api/shipments/{id}/status", status);
    }
}
```

### 5. Register HttpClient and service in Client Program.cs

Edit `ShipmentTracker.Client/Program.cs` to add:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddHttpClient<IShipmentService, ShipmentHttpService>(client =>
{
    client.BaseAddress = new Uri(builder.HostEnvironment.BaseAddress);
});

await builder.Build().RunAsync();
```

Note: You need to add `Microsoft.Extensions.Http` package to the Client project for `AddHttpClient`:
```
dotnet add ShipmentTracker.Client/ShipmentTracker.Client.csproj package Microsoft.Extensions.Http
```

### 6. Create server-side service implementation

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
namespace ShipmentTracker.Services;

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> _shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "TRK-001234", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes" },
        new Shipment { Id = 2, TrackingNumber = "TRK-005678", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(12), CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet" },
        new Shipment { Id = 3, TrackingNumber = "TRK-009012", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "carol@example.com", Description = "Medical supplies" },
        new Shipment { Id = 4, TrackingNumber = "TRK-003456", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "dave@example.com", Description = "Textiles - 5 boxes" },
        new Shipment { Id = 5, TrackingNumber = "TRK-007890", Origin = "São Paulo, BR", Destination = "Paris, FR", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "eve@example.com", Description = "Auto parts" },
    };

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
        {
            shipment.Status = status;
        }
        return Task.CompletedTask;
    }
}
```

### 7. Add API endpoints and register server service in server Program.cs

Edit `ShipmentTracker/Program.cs`. After `builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();` add:

```csharp
builder.Services.AddScoped<IShipmentService, ShipmentServerService>();
```

You'll need these usings at the top:
```csharp
using ShipmentTracker.Client.Services;
using ShipmentTracker.Services;
```

Before `app.Run();`, add API endpoints:
```csharp
// Shipment API endpoints
var shipments = app.MapGroup("api/shipments").RequireAuthorization();

shipments.MapGet("/", async (IShipmentService service) =>
    await service.GetAllShipmentsAsync());

shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

shipments.MapPut("/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
{
    await service.UpdateShipmentStatusAsync(id, status);
    return Results.NoContent();
});
```

You'll also need `using ShipmentTracker.Client.Models;` at the top for `ShipmentStatus`.

### 8. Create Dispatcher page

Create `ShipmentTracker.Client/Pages/Dispatcher.razor`:
```razor
@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Shipment Dashboard</h1>

@if (_shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="_filterText" @bind:event="oninput" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>ETA</th>
                <th>Action</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td>
                    <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                    <td>
                        <select class="form-select form-select-sm" value="@shipment.Status"
                                @onchange="e => UpdateStatus(shipment, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? _shipments;
    private string _filterText = string.Empty;

    private IEnumerable<Shipment> FilteredShipments =>
        _shipments?.Where(s => s.Destination.Contains(_filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
